 43	    public FunctionalMethod(FnDecl ast, TraitObjectDecl traitDecl, List<StaticParam> traitParams) {
 44	        _ast = ast;
 45	        _declaringTrait = NodeUtil.getName(traitDecl);
 46	        _traitParams = CollectUtil.makeList(IterUtil.map(traitParams, liftStaticParam));
 47	        _selfType = traitDecl.getSelfType();
 48	        _declarerIsObject = traitDecl instanceof ObjectDecl;
 49	        int i = 0;
 50	        for (Param p : NodeUtil.getParams(ast)) {
 51	            if (p.getName().equals(NamingCzar.SELF_NAME)) break;
 52	            ++i;
 53	        }
 54	        _selfPosition = i;
 55	
 56	        if (NodeUtil.getReturnType(_ast).isSome())
 57	            _thunk = Option.<Thunk<Option<Type>>>some(SimpleBox.make(NodeUtil.getReturnType(_ast)));
 58	    }
