 61	     * Copy another FunctionalMethod, performing a substitution with the visitor.
 62	     */
 63	    public FunctionalMethod(FunctionalMethod that, List<StaticParam> params, StaticTypeReplacer visitor) {
 64	        _ast = (FnDecl) that._ast.accept(visitor);
 65	        _declaringTrait = that._declaringTrait;
 66	        _traitParams = params;
 67	        _selfType = visitor.recurOnOptionOfSelfType(that._selfType);
 68	        _selfPosition = that._selfPosition;
 69	        _declarerIsObject = that._declarerIsObject;
 70	        _thunk = that._thunk;
 71	        _thunkVisitors = that._thunkVisitors;
 72	        pushVisitor(visitor);
 73	    }
