    public boolean hasQualifiedGrammar(Id name) {
        Option<APIName> optApi = name.getApiName();
        if (optApi.isNone()) bug(name, "Expected to have an API name.");
        APIName api = optApi.unwrap();
        if (_filteredGlobalEnv.definesApi(api)) {
            name = NodeFactory.makeLocalId(name);
            return _filteredGlobalEnv.api(api).grammars().containsKey(name.getText());
        } else {
            return false;
        }
    }

    public TypeConsIndex typeConsIndex(final Id name) {
        Option<APIName> api = name.getApiName();
        APIName actualApi;
        Id actualName = ignoreApi(name);
        // If no API in name or it's the current API, use its own typeCons.
        // Otherwise, try to find the API in the global env and use its typeCons.
        CompilationUnit ast = _current.ast();
        if (api.isNone()) {
            actualApi = ast.getName();
        } else {
            actualApi = api.unwrap();
        }
        if (api.isNone() || (ast instanceof Api && ast.getName().equals(actualApi)) ||
            (ast instanceof Component && ((Component) ast).getExports().contains(actualApi))) {
            Map<Id, TypeConsIndex> typeConses = _current.typeConses();
            if (typeConses.keySet().contains(actualName)) return typeConses.get(actualName);
                //             System.err.println("Lookup of "+name+" in current api was null!\n  Trying qualified lookup, api = "+api);
            else return null;
        }

        // By this point it should be okay to use the unfiltered environment because this
        // method should only be called after the name is disambiguated.
        Map<Id, TypeConsIndex> typeConses = _originalGlobalEnv.api(actualApi).typeConses();
        if (typeConses.keySet().contains(actualName)) {
            return typeConses.get(actualName);
        }
        //         System.err.println("Still couldn't find "+name);
        else return null;
    }

    private Id ignoreApi(Id id) {
        return NodeFactory.makeId(NodeUtil.getSpan(id), id.getText());
    }

    public Option<GrammarIndex> grammarIndex(final Id name) {
        String uqname = name.getText();
        if (name.getApiName().isSome()) {
            APIName n = name.getApiName().unwrap();
            if (_filteredGlobalEnv.definesApi(n)) {
                return Option.some(_filteredGlobalEnv.api(n).grammars().get(uqname));
            } else {
                return Option.none();
            }
        }

 *
 * @param that            The type that is being translated (used as a result when errors
 *                        occur).
 * @param n               The type name to be resolved (provided by {@code that}).
 * @param variableHandler Produces the appropriate result where {@code n} represents
 *                        a type variable.  May assume that {@code n} has no
 *                        API and was not changed.
 * @param typeConsHandler Produce the appropriate result where {@code n} represents
 *                        a type constructor (trait, object, or type alias) name.
 *                        An updated, potentially-qualified version of {@code n} is
 *                        provided.  May assume that the named type constructor
 *                        exists.
 */
private Type handleTypeName(Type that, Id n, Thunk<Type> variableHandler, Lambda<Id, Type> typeConsHandler) {
    if (n.getApiName().isSome()) {
        APIName originalApi = n.getApiName().unwrap();
        Option<APIName> realApiOpt = _env.apiName(originalApi);
        if (realApiOpt.isNone()) {
            // retry for debugging purposes
            //realApiOpt = _env.apiName(originalApi);
            error("Undefined API: " + NodeUtil.nameString(originalApi), originalApi);
            return that;
        }
        APIName realApi = realApiOpt.unwrap();
        Id newN;
        //System.err.println("original " + originalApi);
        //System.err.println("realApi: " + realApi);
        if (originalApi == realApi) {
            newN = n;
        } else {
            newN = NodeFactory.makeId(realApi, n);
        }

        if (!_env.hasQualifiedTypeCons(newN)) {
            error(NodeUtil.nameString(newN) + " is undefined.", newN);
            return that;
        }
        return typeConsHandler.value(newN);
    } else {
        if (_env.hasTypeParam(n).isSome()) {
            return variableHandler.value();
        } else {
            Set<Id> typeConses = _env.explicitTypeConsNames(n);
            if (typeConses.isEmpty()) {
                typeConses = _env.onDemandTypeConsNames(n);
                _onDemandImports.add(n);
            }
            if (typeConses.isEmpty()) {
                // In a typecase clause a bare name that names no type is a binding;
                // a name applied to static arguments cannot be one.
                if (forTypecaseClause && that instanceof VarType)
                    rewriteTypecaseClause = true;
                else
                    error(NodeUtil.nameString(n) + " is undefined.", n);
                return that;
            }
            if (typeConses.size() > 1) {
                error("Type name may refer to: " + NodeUtil.namesString(typeConses), n);
                return that;
            }
            Id qname = IterUtil.first(typeConses);
            Type result = typeConsHandler.value(qname);
            //System.err.println("result type: " + result);
